from pathlib import Path
import difflib,json,hashlib
root=Path(__file__).resolve().parents[4];out=Path(__file__).resolve().parent
changes={
'docs/developer/react-aria-modal-shells.md':[("These modules use owned controls and compiled token CSS; root catalog imports still\ninclude unmigrated components and their peers.","These modules and the root catalog use owned controls and compiled token CSS.\nGranular exports remain available for bounded consumer imports.")],
'docs/developer/react-aria-catalog-grid.md':[("| engine selection include/exclude object | explicit string ID set in selection config |","| upstream row-selection model alias and engine event params | owned `Set<string>` alias and owned callbacks; existing selection config Set values remain |"),("object accepts selected/default ID sets, a change callback and `isRowSelectable`.\n","object accepts selected/default ID sets, a change callback and `isRowSelectable`.\nThe original extracted wrapper omitted convenience selection when `selection` was\nabsent. Pass `selection={false}` to retain that presentation. Existing\n`selection.selectedRowIds` already used `Set<string>` and its callback still returns\na Set; do not convert those callers to an engine include/exclude object. Move\ncustom selection/drag `getRowId` to the top-level prop and return stable strings.\n")],
'docs/migration.md':[("| Engine include/exclude selection and nested identity | Explicit string ID set and top-level getRowId; retained IDs require host reconciliation |","| Upstream row-selection model alias and nested identity | Owned Set alias and top-level string getRowId; existing selection config Set values remain |"),("The [card pagination]","Selection is now enabled when omitted. Pass `selection={false}` to retain the\noriginal extracted wrapper's omitted-selection presentation. Existing\n`selection.selectedRowIds` and its change callback already used Set values; only\nthe upstream model/event contract is replaced. See\n[owned public defaults and validation](developer/react-aria-public-contracts.md) for\ncomponent-specific visual domains, dismissal reasons and field commit ownership.\n\nThe [card pagination]")],
'docs/developer/react-aria-grid-contracts.md':[("Existing selection/drag getRowId conveniences must resolve to that same identity\nor receive a documented breaking mapping.","Move the extracted selection/drag getRowId conveniences to the top-level\ngetRowId prop; custom callbacks must now return strings."),("## Internal cell and presentation batch","## Historical internal cell and presentation batch"),("M-16 now has internal `ownedGridColumns`, `ownedGridCells` and `ownedGridParts`\nmodules. They are preparatory implementations; the exported catalog helpers and\nrenderer still use the retired engine. Do not import these internal paths from a\nconsumer application. The next integration batch will map the public names to\nthese contracts with the breaking consumer documentation.","This section records the earlier preparatory batch, before public integration.\nThe public renderer and helpers now use these owned implementations; see\n[catalog integration](react-aria-catalog-grid.md) for shipped migration mappings.\nConsumers use public exports rather than these private implementation paths."),("Container measurement and pointer/keyboard resizing remain pending.","Container measurement and pointer/keyboard resizing were pending at this\nhistorical preparatory stage; they are implemented in the integrated renderer.")]
}
changes['docs/developer/react-aria-grid-contracts.md'].extend([
("Implement M-16 in linked batches if needed: owned types/row processing, migrated\ncells/header/status parts, registered experimental interaction with native\nrefs/token CSS, then catalog integration and strict transitive/package checks.\nM-17 wires the shared shell transaction; M-18 completes reorder; M-19 migrates\nthe learning composition. Each implementation batch requires colocated behavior\ntests/stories, pnpm check, build-storybook and relevant packed/native evidence.\nDo not weaken registered interaction guards or claim broad G/U/X/R/Z acceptance\nfrom the existing representative proofs. No legacy foundation removal before\nG-27 and the remaining catalog consumers pass.",
"M-16 through M-19 have integrated the owned renderer, shared shell, reorder and\nlearning composition. New examples belong to the docs website and its private\nnative host; Storybook is removed. Follow the [development validation policy](react-aria-development-validation.md) for targeted affected checks and retain\nfull production gates. Registered interaction guards and broad G/U/X/R/Z\nacceptance remain required independently of representative proofs."),
("remaining reorder/reset and broad acceptance gates.","scoped reorder/reset behavior and broader acceptance gates.")])
snippet=(out/'consumer-contracts.tsx').read_text().split('// Guide snippet begins (uses the AppDataGrid import above).\n')[1]
old,new=changes['docs/developer/react-aria-catalog-grid.md'][1]
new+='\n```tsx\nimport { AppDataGrid } from \"@structured-growth/sg-ui\";\n\n'+snippet+'```\n\n'
changes['docs/developer/react-aria-catalog-grid.md'][1]=(old,new)
patch=[];hashes={} 

for p,edits in changes.items():
 before=(root/p).read_text();after=before
 for old,new in edits:
  assert after.count(old)==1,(p,old);after=after.replace(old,new)
 target=out/'proposed-files'/p;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(after)
 hashes[p]=hashlib.sha256(before.encode()).hexdigest()
 patch.extend(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile='a/'+p,tofile='b/'+p))
p='docs/developer/react-aria-public-contracts.md';text=(out/'proposed-files'/p).read_text()
patch.extend(difflib.unified_diff([],text.splitlines(True),fromfile='/dev/null',tofile='b/'+p))
(out/'consumer-guide.patch').write_text(''.join(patch));(out/'patch-inputs.json').write_text(json.dumps(hashes,indent=2)+'\n')
print('Prepared 5 documentation files; patch unapplied.')
